/**
 * RecordSearchService
 *
 * A safe, dynamic "record finder" for Lightning power users. Executes a single
 * SOQL query against any object, with equality filters, an optional ascending
 * ORDER BY, and a LIMIT. All object/field names are validated against schema
 * metadata (case-insensitively) and filter values are passed as SOQL bind
 * variables, so the query is safe against SOQL injection. The query runs in
 * USER_MODE, which enforces record sharing (CRUD) and field-level security
 * for the running user.
 */
public with sharing class RecordSearchService {

    /** Upper bound for maxRows. */
    private static final Integer MAX_ROWS_CEILING = 200;

    /** Raised for every invalid search request or access failure. */
    public class SearchException extends Exception {}

    /**
     * Searches any object with simple equality filters.
     *
     * @param objectApiName  API name of the object to query (case-insensitive).
     * @param fields         API names of the fields to select (case-insensitive).
     *                       Id is always selected.
     * @param filters        Map of field API name -> equality value (may be null/empty).
     *                       Values may be String, Boolean, Date, Decimal, Integer, Id or null.
     * @param orderByField   Field API name to sort by, ascending (may be blank).
     * @param maxRows        Maximum number of rows to return (1..200).
     * @return               Matching records, honoring the user's sharing and FLS.
     * @throws SearchException for any invalid input, missing object/field,
     *                         non-filterable/sortable field, exceeded limit,
     *                         or missing object/field access.
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ------------------------------------------------------------------
        // 1. Validate and describe the object (case-insensitive lookup).
        // ------------------------------------------------------------------
        if (String.isBlank(objectApiName)) {
            throw new SearchException('objectApiName must not be blank.');
        }
        String trimmedObjectName = objectApiName.trim();
        // Apex String-keyed maps are case-insensitive, so this lookup is too.
        Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(trimmedObjectName);
        if (sobjType == null) {
            throw new SearchException('Object does not exist: ' + trimmedObjectName);
        }
        Schema.DescribeSObjectResult objectDescribe = sobjType.getDescribe();
        if (!objectDescribe.isAccessible()) {
            throw new SearchException(
                'Running user does not have read access to object: ' + objectDescribe.getName()
            );
        }
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        // ------------------------------------------------------------------
        // 2. Validate maxRows.
        // ------------------------------------------------------------------
        if (maxRows == null || maxRows < 1 || maxRows > MAX_ROWS_CEILING) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // ------------------------------------------------------------------
        // 3. Validate the requested fields and build the SELECT clause.
        //    Id is always included; duplicates (case-insensitive) are removed.
        // ------------------------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }
        // Apex String-keyed maps are case-insensitive; used as a case-insensitive set.
        Map<String, Boolean> seenFields = new Map<String, Boolean>{'Id' => true};
        List<String> selectItems = new List<String>{'Id'};
        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                throw new SearchException('fields must not contain blank entries.');
            }
            String trimmedFieldName = fieldName.trim();
            if (!fieldMap.containsKey(trimmedFieldName)) {
                throw new SearchException(
                    'Field does not exist on ' + objectDescribe.getName() + ': ' + trimmedFieldName
                );
            }
            Schema.DescribeFieldResult fieldDescribe = fieldMap.get(trimmedFieldName).getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException(
                    'Running user does not have read access to field: ' + trimmedFieldName
                );
            }
            String canonicalName = fieldDescribe.getName();
            if (!seenFields.containsKey(canonicalName)) {
                seenFields.put(canonicalName, true);
                selectItems.add(canonicalName);
            }
        }

        // ------------------------------------------------------------------
        // 4. Validate filter keys and build the WHERE clause. Values are
        //    passed as bind variables so they can never alter the query text.
        // ------------------------------------------------------------------
        List<String> conditions = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter keys must not be blank.');
                }
                String trimmedFilterKey = filterKey.trim();
                if (!fieldMap.containsKey(trimmedFilterKey)) {
                    throw new SearchException(
                        'Filter field does not exist on ' + objectDescribe.getName() + ': ' + trimmedFilterKey
                    );
                }
                Schema.DescribeFieldResult filterFieldDescribe = fieldMap.get(trimmedFilterKey).getDescribe();
                if (!filterFieldDescribe.isAccessible()) {
                    throw new SearchException(
                        'Running user does not have read access to field: ' + trimmedFilterKey
                    );
                }
                if (!filterFieldDescribe.isFilterable()) {
                    throw new SearchException(
                        'Field cannot be used in a filter: ' + trimmedFilterKey
                    );
                }
                String bindKey = 'f' + bindIndex;
                bindIndex++;
                conditions.add(filterFieldDescribe.getName() + ' = :' + bindKey);
                binds.put(bindKey, filters.get(filterKey));
            }
        }

        // ------------------------------------------------------------------
        // 5. Validate the order-by field and build the ORDER BY clause.
        // ------------------------------------------------------------------
        String orderByClause = '';
        if (!String.isBlank(orderByField)) {
            String trimmedOrderByField = orderByField.trim();
            if (!fieldMap.containsKey(trimmedOrderByField)) {
                throw new SearchException(
                    'Order-by field does not exist on ' + objectDescribe.getName() + ': ' + trimmedOrderByField
                );
            }
            Schema.DescribeFieldResult orderByFieldDescribe = fieldMap.get(trimmedOrderByField).getDescribe();
            if (!orderByFieldDescribe.isAccessible()) {
                throw new SearchException(
                    'Running user does not have read access to field: ' + trimmedOrderByField
                );
            }
            if (!orderByFieldDescribe.isSortable()) {
                throw new SearchException(
                    'Field cannot be used to sort: ' + trimmedOrderByField
                );
            }
            orderByClause = ' ORDER BY ' + orderByFieldDescribe.getName() + ' ASC';
        }

        // ------------------------------------------------------------------
        // 6. Assemble and execute the single query in user mode
        //    (enforces sharing, CRUD and FLS for the running user).
        // ------------------------------------------------------------------
        String soql = 'SELECT ' + String.join(selectItems, ', ')
            + ' FROM ' + objectDescribe.getName();
        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        soql += orderByClause + ' LIMIT ' + maxRows;

        try {
            return Database.queryWithBinds(soql, binds, System.AccessLevel.USER_MODE);
        } catch (Exception e) {
            // Guarantee the contract: only SearchException ever escapes this service.
            throw new SearchException('Search query failed: ' + e.getMessage());
        }
    }
}
