public inherited sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public static Order parse(String body) {
        if (body == null || body.trim() == '') {
            throw new PayloadException('Request body must not be null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body must be a JSON object.');
        }
        Map<String, Object> root = (Map<String, Object>) parsed;

        // number: required, non-blank
        Object numberObj = root.get('number');
        if (numberObj == null || !(numberObj instanceof String) || ((String) numberObj).trim() == '') {
            throw new PayloadException('Missing or blank "number".');
        }

        Order order = new Order();
        order.orderNumber = (String) numberObj;

        // date: optional, ISO yyyy-MM-dd
        Object dateObj = root.get('date');
        if (dateObj instanceof String && ((String) dateObj).trim() != '') {
            try {
                order.orderDate = Date.valueOf(((String) dateObj).trim());
            } catch (Exception e) {
                order.orderDate = null;
            }
        }

        // currency: optional
        Object currencyObj = root.get('currency');
        if (currencyObj instanceof String) {
            order.currencyCode = (String) currencyObj;
        }

        // customer: optional
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Object emailObj = ((Map<String, Object>) customerObj).get('email');
            if (emailObj instanceof String) {
                order.customerEmail = (String) emailObj;
            }
        }

        // lines: optional
        Object linesObj = root.get('lines');
        List<Object> lineList = (List<Object>) linesObj;

        if (lineList != null) {
            for (Object lineObj : lineList) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be a JSON object.');
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                Line line = new Line();

                // sku: required (present)
                Object skuObj = lineMap.get('sku');
                if (skuObj == null) {
                    throw new PayloadException('Line is missing "sku".');
                }
                line.sku = String.valueOf(skuObj);

                // quantity: required, positive
                line.quantity = toInteger(lineMap.get('quantity'), 'quantity');
                if (line.quantity == null || line.quantity <= 0) {
                    throw new PayloadException('Line "quantity" must be present and positive.');
                }

                // unitPrice: required, non-negative
                line.unitPrice = toDecimal(lineMap.get('unitPrice'), 'unitPrice');
                if (line.unitPrice == null || line.unitPrice < 0) {
                    throw new PayloadException('Line "unitPrice" must be present and non-negative.');
                }

                // discount: optional, defaults to 0
                Object discountObj = lineMap.get('discount');
                if (discountObj == null) {
                    line.discount = 0;
                } else {
                    line.discount = toDecimal(discountObj, 'discount');
                }

                line.lineTotal = (line.quantity * line.unitPrice * (1 - line.discount))
                    .setScale(2, System.RoundingMode.HALF_UP);

                order.lines.add(line);
            }
        }

        Decimal total = 0;
        for (Line line : order.lines) {
            total += line.lineTotal;
        }
        order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => order.lines.size(),
            'total' => order.total
        };
        return JSON.serialize(ack);
    }

    private static Integer toInteger(Object value, String fieldName) {
        if (value instanceof Integer) {
            return (Integer) value;
        }
        if (value instanceof Decimal) {
            Decimal d = (Decimal) value;
            if (d == d.round(System.RoundingMode.DOWN)) {
                return Integer.valueOf(d.intValue());
            }
            return null;
        }
        return null;
    }

    private static Decimal toDecimal(Object value, String fieldName) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        return null;
    }
}
