public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    /**
     * Imports leads with per-row error reporting.
     * - Partial success: every insertable lead is inserted in a single DML statement.
     * - Blank LeadSource is defaulted to 'Web'.
     * - Duplicate emails within the call (case-insensitive, trimmed) are rejected
     *   before DML; the first occurrence wins even if it later fails to insert.
     * - Leads without an email are never considered duplicates.
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        // Null or empty input: return empty (non-null) members.
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Normalize: default LeadSource, resolve duplicates within the call.
        Set<String> seenEmails = new Set<String>();
        List<Lead> toInsert = new List<Lead>();
        Map<Integer, Integer> indexByInsertPosition = new Map<Integer, Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            if (lead == null) {
                result.errorsByIndex.put(i, 'Lead record cannot be null.');
                continue;
            }

            // Default LeadSource to 'Web' when blank.
            if (lead.LeadSource == null || lead.LeadSource.trim() == '') {
                lead.LeadSource = 'Web';
            }

            // Duplicate detection: trimmed, lower-cased email. Leads without
            // an email are never duplicates.
            String normalizedEmail = null;
            if (lead.Email != null) {
                normalizedEmail = lead.Email.trim().toLowerCase();
            }

            if (normalizedEmail != null) {
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            indexByInsertPosition.put(toInsert.size(), i);
            toInsert.add(lead);
        }

        if (toInsert.isEmpty()) {
            return result;
        }

        // Single DML statement, partial success allowed.
        List<Database.SaveResult> saveResults = Database.insert(toInsert, false);

        for (Integer position = 0; position < saveResults.size(); position++) {
            Database.SaveResult saveResult = saveResults[position];
            Integer inputIndex = indexByInsertPosition.get(position);

            if (saveResult.isSuccess()) {
                result.insertedIds.add(saveResult.getId());
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : saveResult.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(inputIndex, String.join(messages, '; '));
            }
        }

        result.successCount = result.insertedIds.size();
        return result;
    }
}
