/**
 * Utility service that resolves the active picklist entries of any picklist or
 * multi-select picklist field (standard or custom) at runtime, using only API
 * names supplied by the caller.
 *
 * All failure modes (null/blank names, unknown object, unknown field, field
 * that is not a picklist/multi-select picklist) are surfaced as
 * PicklistService.PicklistServiceException so callers only ever have to catch
 * one exception type.
 */
public inherited sharing class PicklistService {

    /**
     * One active picklist entry.
     */
    public class Option {
        /** The API value of the picklist entry. */
        public String value;
        /** The user-facing label of the picklist entry. */
        public String label;
        /** True only for the field's default value. */
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Custom exception so callers can catch a single, well-known type.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the requested picklist or multi-select
     * picklist field, in the order they are defined on the field.
     *
     * @param  objectApiName  API name of the object (case-insensitive), e.g. 'account' or 'FB_Asset_Check__c'
     * @param  fieldApiName   API name of the field (case-insensitive), e.g. 'INDUSTRY' or 'Status__c'
     * @return                Active entries only, in definition order
     * @throws PicklistServiceException when a name is null/blank, the object does not exist,
     *         the field does not exist on the object, or the field is not a
     *         picklist / multi-select picklist
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        // --- Validate inputs -------------------------------------------------
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        String objectKey = objectApiName.trim().toLowerCase();
        String fieldKey = fieldApiName.trim().toLowerCase();

        // --- Resolve the object (case-insensitively) -------------------------
        Schema.SObjectType sobjectType = resolveSObjectType(objectKey);
        if (sobjectType == null) {
            throw new PicklistServiceException(
                'Object does not exist or is not accessible: ' + objectApiName.trim()
            );
        }

        // --- Resolve the field on that object (case-insensitively) -----------
        Schema.DescribeSObjectResult objectDescribe = sobjectType.getDescribe();
        Schema.SObjectField field = resolveField(objectDescribe, fieldKey);
        if (field == null) {
            throw new PicklistServiceException(
                'Field does not exist on object ' + objectDescribe.getName()
                + ': ' + fieldApiName.trim()
            );
        }

        // --- Validate that the field is a picklist / multi-select picklist ---
        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST
            && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + objectDescribe.getName() + '.' + fieldApiName.trim()
                + ' is not a picklist or multi-select picklist.'
            );
        }

        // --- Collect active entries in definition order -----------------------
        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }
        return options;
    }

    /**
     * Case-insensitive lookup of an SObjectType from the global describe.
     * Returns null when the object is not known to the org.
     */
    private static Schema.SObjectType resolveSObjectType(String lowercasedObjectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        // The global describe map keys are lowercase; do an explicit case-insensitive
        // scan as well so lookup behavior never depends on platform key casing.
        Schema.SObjectType sobjectType = globalDescribe.get(lowercasedObjectApiName);
        if (sobjectType != null) {
            return sobjectType;
        }
        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase() == lowercasedObjectApiName) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    /**
     * Case-insensitive lookup of a field on the given object's describe.
     * Returns null when the field does not exist on the object.
     */
    private static Schema.SObjectField resolveField(
        Schema.DescribeSObjectResult objectDescribe,
        String lowercasedFieldApiName
    ) {
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();
        Schema.SObjectField field = fieldMap.get(lowercasedFieldApiName);
        if (field != null) {
            return field;
        }
        for (String key : fieldMap.keySet()) {
            if (key.toLowerCase() == lowercasedFieldApiName) {
                return fieldMap.get(key);
            }
        }
        return null;
    }
}
