public inherited sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work so that every run,
        // successful or failed, is logged and failures are retried.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            acc.Description = 'Synced to ERP';
        }

        // Single DML statement: all-or-nothing. If any account cannot be
        // saved, the exception is not caught, so the job fails and none of
        // its changes are kept (the failed transaction is rolled back).
        update accounts;
    }
}
