@isTest
private class OpportunityCleanupServiceTest {

    private static final Date CUTOFF = Date.newInstance(2025, 6, 30);

    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector selectorMock;
    private static fflib_ISObjectUnitOfWork uowMock;

    private static void givenMockedSelectorAndUnitOfWork() {
        mocks = new fflib_ApexMocks();
        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.UnitOfWork.setMock(uowMock);
    }

    private static void givenSelectorReturns(Set<Id> opportunityIds, List<Opportunity> opportunities) {
        mocks.startStubbing();
        mocks.when(selectorMock.selectById(opportunityIds)).thenReturn(opportunities);
        mocks.stopStubbing();
    }

    private static Opportunity opportunity(Id oppId, String name, String stageName, Date closeDate) {
        return new Opportunity(
            Id = oppId,
            Name = name,
            StageName = stageName,
            CloseDate = closeDate
        );
    }

    /**
     * The record the service is expected to register for a stale opportunity:
     * untouched fields preserved, StageName set to 'Closed Lost' and Description
     * set to OpportunityCleanupService.LOST_REASON.
     */
    private static Opportunity expectedClosedLost(Opportunity original) {
        return new Opportunity(
            Id = original.Id,
            Name = original.Name,
            StageName = 'Closed Lost',
            CloseDate = original.CloseDate,
            Description = OpportunityCleanupService.LOST_REASON
        );
    }

    @isTest
    static void closesOnlyStaleOpenOpportunitiesAndCommitsOnce() {
        givenMockedSelectorAndUnitOfWork();

        Id stale1Id = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id stale2Id = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id onCutoffId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id futureId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id wonId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id lostId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id noCloseDateId = fflib_IDGenerator.generate(Opportunity.SObjectType);

        // Stale: open (not closed-won/lost) and CloseDate strictly before the cutoff.
        Opportunity stale1 = opportunity(stale1Id, 'Stale 1', 'Prospecting', CUTOFF.addDays(-1));
        Opportunity stale2 = opportunity(stale2Id, 'Stale 2', 'Negotiation/Review', CUTOFF.addDays(-30));
        // Not stale: closes on the cutoff date itself (not strictly before).
        Opportunity onCutoff = opportunity(onCutoffId, 'Closing on cutoff date', 'Qualification', CUTOFF);
        // Not stale: closes after the cutoff.
        Opportunity future = opportunity(futureId, 'Closing after cutoff date', 'Prospecting', CUTOFF.addDays(7));
        // Not stale: already closed, even though the close date is before the cutoff.
        Opportunity won = opportunity(wonId, 'Already closed won', 'Closed Won', CUTOFF.addDays(-10));
        Opportunity lost = opportunity(lostId, 'Already closed lost', 'Closed Lost', CUTOFF.addDays(-10));
        // Not stale: no close date can never be strictly before the cutoff.
        Opportunity noCloseDate = opportunity(noCloseDateId, 'No close date', 'Prospecting', null);

        Set<Id> opportunityIds = new Set<Id>{
            stale1Id, stale2Id, onCutoffId, futureId, wonId, lostId, noCloseDateId
        };
        givenSelectorReturns(
            opportunityIds,
            new List<Opportunity>{ stale1, stale2, onCutoff, future, won, lost, noCloseDate }
        );

        Test.startTest();
        Integer closed = OpportunityCleanupService.closeStale(opportunityIds, CUTOFF);
        Test.stopTest();

        // Returns the number of opportunities it closed.
        Assert.areEqual(2, closed, 'Only the two stale, open opportunities should be closed');

        // The selector was queried exactly once with the ids passed in.
        ((IOpportunitiesSelector) mocks.verify(selectorMock, mocks.times(1)))
            .selectById(opportunityIds);

        // Each stale opportunity was registered dirty exactly once, with the
        // expected StageName and Description (and all other fields untouched).
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.times(1)))
            .registerDirty(expectedClosedLost(stale1));
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.times(1)))
            .registerDirty(expectedClosedLost(stale2));

        // No other opportunity was registered.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(onCutoff);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(future);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(won);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(lost);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(noCloseDate);

        // commitWork was called exactly once because at least one opportunity was closed.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.times(1))).commitWork();
    }

    @isTest
    static void registersAndCommitsNothingWhenNoOpportunityIsStale() {
        givenMockedSelectorAndUnitOfWork();

        Id onCutoffId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id futureId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id wonId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id lostId = fflib_IDGenerator.generate(Opportunity.SObjectType);

        Opportunity onCutoff = opportunity(onCutoffId, 'Closing on cutoff date', 'Prospecting', CUTOFF);
        Opportunity future = opportunity(futureId, 'Closing after cutoff date', 'Value Proposition', CUTOFF.addDays(1));
        Opportunity won = opportunity(wonId, 'Already closed won', 'Closed Won', CUTOFF.addDays(-5));
        Opportunity lost = opportunity(lostId, 'Already closed lost', 'Closed Lost', CUTOFF.addDays(-5));

        Set<Id> opportunityIds = new Set<Id>{ onCutoffId, futureId, wonId, lostId };
        givenSelectorReturns(opportunityIds, new List<Opportunity>{ onCutoff, future, won, lost });

        Integer closed = OpportunityCleanupService.closeStale(opportunityIds, CUTOFF);

        Assert.areEqual(0, closed, 'No opportunity should be closed');

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(onCutoff);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(future);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(won);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerDirty(lost);

        // commitWork must never be called when nothing was closed.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).commitWork();
    }

    @isTest
    static void returnsZeroForNullIds() {
        givenMockedSelectorAndUnitOfWork();

        Integer closed = OpportunityCleanupService.closeStale(null, CUTOFF);

        Assert.areEqual(0, closed, 'Null ids must return 0');
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).commitWork();
    }

