/**
 * Domain (collection) class for Account records, built on fflib_SObjects.
 *
 * Instances are created through the Application.Domain factory:
 *   - Accounts.newInstance(records) / Accounts.newInstance(accountIds)
 *   - or indirectly by fflib code via Accounts.Constructor
 *
 * Unit tests replace the factory with Application.Domain.setMock(...),
 * so no instance construction is done outside the factory path for callers.
 */
public inherited sharing class Accounts extends fflib_SObjects implements IAccounts
{
    public Accounts(List<Account> records)
    {
        super(records);
    }

    /**
     * Builds a domain instance from the given records through the
     * Application.Domain factory (mockable in unit tests).
     */
    public static IAccounts newInstance(List<Account> records)
    {
        return (IAccounts) Application.Domain.byRecords(records);
    }

    /**
     * Loads the given Account ids through the selector wired into the
     * Application.Domain factory and returns a domain instance for them.
     */
    public static IAccounts newInstance(Set<Id> accountIds)
    {
        return (IAccounts) Application.Domain.byIds(accountIds);
    }

    public override Schema.SObjectType getSObjectType()
    {
        return Account.SObjectType;
    }

    public override String getType()
    {
        return Account.SObjectType.getDescribe().getName();
    }

    /**
     * The records held by this domain, as List<Account>.
     */
    public List<Account> getAccounts()
    {
        return (List<Account>) getRecords();
    }

    /**
     * Returns a new domain holding only the records whose Rating equals the
     * given rating (an empty domain when none match). This domain instance
     * is not modified.
     */
    public IAccounts selectByRating(String rating)
    {
        List<Account> selectedRecords = new List<Account>();

        for (Account record : getAccounts())
        {
            if (record.Rating == rating)
            {
                selectedRecords.add(record);
            }
        }

        return new Accounts(selectedRecords);
    }

    /**
     * Distinct, non-null OwnerId values across all records in the domain.
     */
    public Set<Id> getOwnerIds()
    {
        Set<Id> ownerIds = new Set<Id>();

        for (Account record : getAccounts())
        {
