/**
 * Domain class for Opportunity (Apex Enterprise Patterns).
 *
 * Validation rules implemented in the fflib validation hook (onValidate):
 *   1. On insert and on update, Amount must not be negative.
 *   2. On update, an opportunity whose stage was already 'Closed Won' before the
 *      update cannot have its Amount changed. (Closing as won and changing the
 *      amount in the same update is allowed, because the pre-update stage was
 *      not yet 'Closed Won'.)
 *
 * Errors are raised via the domain's error(message, record, field) helper so
 * they are applied to the Amount field of the offending record only (records
 * in the same DML that pass validation still save) and are recorded in
 * fflib_SObjectDomain.Errors for unit test assertions.
 *
 * Bulk-safe by design (single loop over the records) and requires no SOQL.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String FIELD_AMOUNT = 'Amount';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    public override void onValidate()
    {
        // oldMap is only populated by the framework on update events,
        // so this flag drives which rules are applicable per event.
        Boolean isUpdate = oldMap != null;

        for (Opportunity record : (List<Opportunity>) records)
        {
            // Rule 1: applies on insert and on update.
            // A null Amount is allowed (not required), only negative values are rejected.
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, FIELD_AMOUNT);
            }

            // Rule 2: applies on update only. If the stage was already 'Closed Won'
            // before the update, the Amount may not change. Changing the amount in
            // the same update that closes the deal as won is allowed, because the
            // pre-update (oldMap) stage is not 'Closed Won' in that case.
            if (isUpdate)
            {
                Opportunity beforeUpdate = (Opportunity) oldMap.get(record.Id);
                if (beforeUpdate.StageName == STAGE_CLOSED_WON
                    && record.Amount != beforeUpdate.Amount)
                {
                    error('Amount cannot change on a won opportunity.', record, FIELD_AMOUNT);
                }
            }
        }
    }
}
