    /**
     * Returns the open opportunities (IsClosed = false) of the given accounts,
     * highest Amount first; opportunities without an Amount are returned after
     * all others (Amount DESC NULLS LAST); equal amounts are ordered by
     * CloseDate ascending (earliest first), with a final deterministic
     * tiebreaker on opportunity Name.
     *
     * The query is built from the selector's query factory, so the selector's
     * standard field list and its security configuration (CRUD/FLS enforcement)
     * keep applying. Executes as a single query, limited to maxRecords rows.
     *
     * @param accountIds  the parent account Ids; must be non-empty
     * @param maxRecords  maximum number of rows to return; null means no limit
     * @return the matching opportunities, including the parent account Name
     *         accessible via Opportunity.Account.Name
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Guard: nothing to query
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        // Builds SELECT <selector's standard field list> FROM Opportunity,
        // honouring the selector's security configuration.
        fflib_QueryFactory queryFactory = getQueryFactory();

        // Parent account's Name (returned via Opportunity.Account.Name)
        queryFactory.addField('Account.Name');

        // Open opportunities of the given accounts (bind variable is bulk-safe:
        // no values are concatenated into the query string)
        queryFactory.setCondition('AccountId IN :accountIds AND IsClosed = false');

        // Highest Amount first, NULLS LAST; then earliest CloseDate; then Name
        queryFactory.setSortOrder('Amount DESC NULLS LAST, CloseDate ASC, Name ASC');

        // At most maxRecords rows (a single query; LIMIT applied in the same SOQL)
        if (maxRecords != null) {
            if (maxRecords < 0) {
                throw new IllegalArgumentException('maxRecords must not be negative');
            }
            queryFactory.setLimit(maxRecords);
        }

        return (List<Opportunity>) Database.query(queryFactory.toSoql());
    }
}
