```apex
public with sharing class AccountOnboardingService {

    /**
     * @description Creates one Account per map key and one Contact per last name
     *              under that Account. All inserts are performed through a single
     *              fflib_SObjectUnitOfWork and committed once with commitWork().
     * @param  contactLastNamesByAccountName Map of Account Name -> List of Contact LastNames.
     * @return The newly inserted Accounts, with their Ids populated after the commit.
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> newAccounts = new List<Account>();

        // Nothing to do: return an empty list and perform no writes.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        // Single Unit of Work. Registration order of SObjectTypes governs the
        // commit order (Accounts before Contacts), and fflib also resolves
        // child relationships by lookup field within the same commit.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        // Stage Accounts and their Contacts in memory first, registering them
        // with the UoW. Contacts are related to their Account via the lookup
        // field registration (registerNew(child, field, parent)), so no Ids
        // are needed before the commit and no DML is issued here.
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account newAccount = new Account(Name = accountName);
            newAccounts.add(newAccount);
            uow.registerNew(newAccount);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null || lastNames.isEmpty()) {
                continue;
            }

            for (String lastName : lastNames) {
                if (lastName == null) {
                    continue;
                }
                Contact newContact = new Contact(LastName = lastName);
                uow.registerNew(newContact, Contact.AccountId, newAccount);
            }
        }

        // One atomic commit: inserts Accounts first, then Contacts, with Ids
        // written back onto the in-memory Account instances.
        uow.commitWork();

        return newAccounts;
    }
}
