                continue;
            }

            unitOfWork.registerDirty(new Opportunity(
                Id = opportunity.Id,
                StageName = 'Closed Won',
                CloseDate = Date.today()
            ));

            unitOfWork.registerNew(new Deal_Won__e(
                Opportunity_Id__c = opportunity.Id,
                Amount__c = opportunity.Amount
            ));

            closedCount++;
        }

        // Single commit: opportunities are updated first, then the registered
        // Deal_Won__e platform events are published by the unit of work only
        // after the DML has succeeded. If the DML fails, commitWork throws and
        // no events are published.
        unitOfWork.commitWork();

        return closedCount;
    }
}
