public with sharing class CasePriorityHandler {

    // Values kept as constants so admins can change picklist wording in one place.
    private static final String HOT_RATING = 'Hot';
    private static final String HIGH_PRIORITY = 'High';

    /**
     * Before-insert logic: any case whose Account has Rating = 'Hot'
     * gets Priority = 'High'. Cases with no account (or an account that
     * is not 'Hot') keep whatever Priority they were created with.
     *
     * Runs before insert, so no DML is needed – we just set the field.
     */
    public static void setPriorityForHotAccounts(List<Case> newCases) {

        // Collect the AccountIds we care about, skipping cases without an account.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // One query for the whole batch (see note in assessment about bulkifying).
        Map<Id, Account> accountsById = accountIds.isEmpty()
            ? new Map<Id, Account>()
            : new Map<Id, Account>([
                SELECT Id, Rating
                FROM Account
                WHERE Id IN :accountIds
            ]);

        for (Case c : newCases) {
            // get() safely returns null for cases with no AccountId.
            Account acct = accountsById.get(c.AccountId);
            if (acct != null && acct.Rating == HOT_RATING) {
                c.Priority = HIGH_PRIORITY;
            }
            // No else-branch: all other cases keep their original Priority.
        }
    }
}
