            Deal_Stage_Change__e changeEvent = new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c          = opp.StageName,
                Amount__c         = opp.Amount
            );

            // One publish call per event so the SaveResult in the returned list maps
            // 1:1 to the input record, letting the caller see exactly which event failed.
            results.add(EventBus.publish(changeEvent));
        }

        return results;
    }
