```apex
/**
 * Creates a follow-up Task for each opportunity coming out of the weekly
 * pipeline review, owned by the opportunity's owner and due in 7 days.
 *
 * Returns the Ids of the opportunities for which the Task could NOT be
 * created (e.g. blocked by a validation rule), so one rejection never
 * blocks the others. Empty set when every task was created.
 *
 * Implementation note: inserts are done as a single partial-success DML
 * (Database.insert with allOrNone=false) instead of one insert per row in
 * a loop. The review passes 150-250 opportunities in one call, and
 * per-row DML would exceed the 150-DML-statement governor limit and kill
 * the whole transaction. Partial success preserves the required behavior:
 * validation-rule failures on one task do not affect the others.
 */
public inherited sharing class FollowUpTaskService {

    private static final Integer DUE_IN_DAYS = 7;
    private static final String TASK_SUBJECT_PREFIX = 'Follow up: ';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';

    /**
     * @param opportunityIds the opportunities from the pipeline review.
     * @return Ids of opportunities whose task could not be created.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Deduplicate: an opportunity reviewed twice should only get one task.
        Set<Id> requestedIds = new Set<Id>(opportunityIds);

        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>(
            [SELECT Id, Name, OwnerId
             FROM Opportunity
             WHERE Id IN :requestedIds]
        );

        List<Task> tasksToInsert = new List<Task>();
        List<Id> taskOpportunityIds = new List<Id>(); // parallel index -> opportunity Id
        Date dueDate = Date.today().addDays(DUE_IN_DAYS);

        for (Id opportunityId : requestedIds) {
            Opportunity opp = opportunities.get(opportunityId);
            if (opp == null) {
                // Opportunity no longer exists (or caller passed a bad Id):
                // report it as failed rather than silently dropping it.
                failedOpportunityIds.add(opportunityId);
                continue;
            }
            tasksToInsert.add(new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = TASK_SUBJECT_PREFIX + opp.Name,
                ActivityDate = dueDate,
                Status       = TASK_STATUS,
                Priority     = TASK_PRIORITY
            ));
            taskOpportunityIds.add(opp.Id);
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        // Partial-success insert: rows rejected by validation rules (or any
        // other error) fail individually; all other rows are committed.
        List<Database.SaveResult> saveResults = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];
            if (!result.isSuccess()) {
                failedOpportunityIds.add(taskOpportunityIds[i]);
                // Errors are available here for logging/debugging if needed:
                // for (Database.Error err : result.getErrors()) { ... }
            }
        }

        return failedOpportunityIds;
    }
}
```

