```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    error;
    showResults = false;

    pendingTimeoutId;
    requestId = 0;
    isDisconnected = false;

    handleSearchChange(event) {
        this.searchTerm = event.target.value;

        // Reset any previously scheduled search; only the latest keystroke counts.
        if (this.pendingTimeoutId) {
            clearTimeout(this.pendingTimeoutId);
            this.pendingTimeoutId = undefined;
        }

        const trimmed = (this.searchTerm || '').trim();

        if (trimmed.length < MIN_SEARCH_LENGTH) {
            // Too short: clear pending search and results, no Apex call.
            this.contacts = [];
            this.error = undefined;
            this.showResults = false;
            this.requestId++; // invalidate any in-flight request
            return;
        }

        this.pendingTimeoutId = setTimeout(() => {
            this.pendingTimeoutId = undefined;
            this.performSearch(trimmed);
        }, DEBOUNCE_DELAY_MS);
    }

    async performSearch(trimmedSearchTerm) {
        const currentRequestId = ++this.requestId;

        if (this.isDisconnected) {
            return;
        }

        try {
            const results = await searchContacts({ searchTerm: trimmedSearchTerm });

            // Ignore stale responses and responses after disconnect.
            if (this.isDisconnected || currentRequestId !== this.requestId) {
                return;
            }

            this.contacts = results;
            this.error = undefined;
            this.showResults = true;
        } catch (error) {
            if (this.isDisconnected || currentRequestId !== this.requestId) {
                return;
            }
            this.contacts = [];
            this.error = error;
            this.showResults = true;
        }
    }

    get hasResults() {
        return this.contacts.length > 0;
    }

    disconnectedCallback() {
        this.isDisconnected = true;
        if (this.pendingTimeoutId) {
            clearTimeout(this.pendingTimeoutId);
            this.pendingTimeoutId = undefined;
        }
        this.requestId++; // invalidate any in-flight request
    }
}
