import { LightningElement, wire } from 'lwc';
import { MessageContext, subscribe, unsubscribe, publish, APPLICATION_SCOPE } from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    recordId;

    @wire(MessageContext)
    wiredMessageContext(context) {
        this._messageContext = context;
        // Subscribe as soon as the context is provisioned (component inserted).
        if (context) {
            this.subscribeToMessageChannel();
        }
    }

    _messageContext;
    _subscription = null;

    subscribeToMessageChannel() {
        // Never hold more than one active subscription.
        if (this._subscription) {
            return;
        }
        this._subscription = subscribe(
            this._messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeToMessageChannel() {
        unsubscribe(this._subscription);
        this._subscription = null;
    }

    connectedCallback() {
        // Handles re-insertion (e.g. a tab being reopened): resubscribe if
        // the context is already available at this point.
        if (this._messageContext) {
            this.subscribeToMessageChannel();
        }
    }

    disconnectedCallback() {
        this.unsubscribeToMessageChannel();
    }

    handleMessage(message) {
        this.recordId = message && message.recordId ? message.recordId : null;
    }

    handleClear() {
        publish(this._messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
    }
}
