import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    showError = false;

    get hasLines() {
        return Array.isArray(this.lines) && this.lines.length > 0;
    }

    /** Returns the line editors in display (DOM) order. */
    getEditors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    handleReset() {
        this.showError = false;
        this.getEditors().forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.getEditors();

        // Validate every editor, even after one fails, so all invalid lines
        // show their errors at once.
        const results = editors.map((editor) => editor.validate());

        if (results.every((isValid) => isValid)) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
