            // 60-second cadence aligned with this moment.
            this.loadStats();
            this.startPolling();
        }
    };

    connectedCallback() {
        this.isConnected = true;
        document.addEventListener(
            'visibilitychange',
            this.handleVisibilityChange
        );
        // Initial load plus the recurring refresh loop.
        this.loadStats();
        this.startPolling();
    }

    disconnectedCallback() {
        this.isConnected = false;
        this.stopPolling();
        document.removeEventListener(
            'visibilitychange',
            this.handleVisibilityChange
        );
    }

    /**
     * Starts (or restarts) the polling loop. Always clears any existing timer
     * first so there is only ever one polling loop running at a time.
     */
    startPolling() {
        this.stopPolling();
        this.refreshTimerId = setInterval(() => {
            this.refresh();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this.refreshTimerId !== undefined) {
            clearInterval(this.refreshTimerId);
            this.refreshTimerId = undefined;
        }
    }

    /**
     * A scheduled refresh. Skips if a request is already in flight or if the
     * page is hidden in a background tab.
     */
    refresh() {
        if (this.isRequestInFlight) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }
        this.loadStats();
    }

    async loadStats() {
        if (this.isRequestInFlight) {
            return;
        }
        this.isRequestInFlight = true;
        try {
            const stats = await getQueueStats();
            if (!this.isConnected) {
                return;
            }
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.isLoaded = true;
            // A successful refresh clears any previous error.
            this.error = undefined;
        } catch (e) {
            if (!this.isConnected) {
                return;
            }
            this.error = e;
        } finally {
            this.isRequestInFlight = false;
        }
    }
}
