import { LightningElement, api } from 'lwc';

/**
 * Keys whose default behaviour is suppressed while the listbox has focus.
 * Everything else (notably Tab) is left untouched.
 */
const HANDLED_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    /** Accessible name of the listbox, exposed as aria-label. */
    @api label;

    /** Array of { value, label }. */
    @api options = [];

    /** Currently selected value (may be empty). */
    _value;

    /** Index of the active option once the user has moved it. */
    _activeIndex;

    /** True once the user has moved the active option with keyboard/mouse. */
    _activeMoved = false;

    /** Unique prefix so ids stay unique if multiple instances are on a page. */
    _uid = `status-listbox-${Math.random().toString(36).slice(2, 10)}`;

    // ------------------------------------------------------------------
    // Public API: value
    // ------------------------------------------------------------------

    @api
    get value() {
        return this._value ?? '';
    }

    set value(newValue) {
        this._value = newValue ?? '';
        // The active option follows the value set by the parent.
        this._activeMoved = false;
    }

    // ------------------------------------------------------------------
    // Derived state
    // ------------------------------------------------------------------

    indexOfValue(value) {
        return this.options.findIndex((option) => option.value === value);
    }

    get selectedIndex() {
        const idx = this.indexOfValue(this._value);
        return idx === -1 ? -1 : idx;
    }

    get activeIndex() {
        // Once the user has moved the highlight, it stays where they put it
        // (moving does not change the selection). Before that, the active
        // option mirrors the selection, or defaults to the first option.
        if (this._activeMoved && this._activeIndex != null) {
            return this._activeIndex;
        }
        const idx = this.indexOfValue(this._value);
        return idx === -1 ? 0 : idx;
    }

    get activeId() {
        if (!this.options.length) {
            return undefined;
        }
        return this.optionId(this.activeIndex);
    }

    optionId(index) {
        return `${this._uid}-option-${index}`;
    }

    /**
     * Options decorated for rendering: stable id, data-value,
     * aria-selected as the string "true"/"false", and an active flag.
     */
    get items() {
        return this.options.map((option, index) => ({
            ...option,
            index,
            id: this.optionId(index),
            selected: option.value === this._value ? 'true' : 'false',
            isActive: index === this.activeIndex,
            cssClasses: [
                'status-listbox__option',
                index === this.activeIndex ? 'status-listbox__option_active' : '',
                option.value === this._value ? 'status-listbox__option_selected' : '',
            ]
                .filter(Boolean)
                .join(' '),
        }));
    }

    // ------------------------------------------------------------------
    // Event handling
    // ------------------------------------------------------------------

    handleKeyDown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.includes(key)) {
            // Leave every other key (e.g. Tab) alone.
            return;
        }

        event.preventDefault();

        const count = this.options.length;
        if (!count) {
            return;
        }

        let index = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                index = Math.min(index + 1, count - 1);
                break;
            case 'ArrowUp':
                index = Math.max(index - 1, 0);
                break;
            case 'Home':
                index = 0;
                break;
            case 'End':
                index = count - 1;
                break;
            case 'Enter':
            case ' ':
                this.select(index);
                return;
            default:
                return;
        }

        // Moving the active option never changes the selection.
        this._activeIndex = index;
        this._activeMoved = true;
    }

    handleClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this.options.findIndex((option) => option.value === clickedValue);
        if (index === -1) {
            return;
        }

        // Clicking an option always makes it the active option...
        this._activeIndex = index;
        this._activeMoved = true;

        // ...and selects it (unless it was already selected).
        this.select(index);
    }

    /**
     * Selects the option at the given index and dispatches `change`,
     * unless that option is already selected.
     */
    select(index) {
        const option = this.options[index];
        if (!option || option.value === this._value) {
            return;
        }

        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
            })
        );
    }
}
