<template>
    <ul
        class="status-listbox"
        role="listbox"
        tabindex="0"
        aria-label={label}
        aria-activedescendant={activeId}
        onkeydown={handleKeyDown}
    >
        <template for:each={items} for:item="item">
            <li
                key={item.id}
                role="option"
                id={item.id}
                class={item.cssClasses}
                data-value={item.value}
                aria-selected={item.selected}
                onclick={handleClick}
            >
                {item.label}
            </li>
        </template>
    </ul>
