import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading = '';

    _items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._items;
    }

    set tasks(value) {
        // Work on our own deep-enough copy: never mutate the parent's array or task objects.
        this._items = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
    }

    // Display-only transformation: the @api heading value itself is never modified,
    // so later changes from the parent are always reflected.
    get headingUpper() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this._items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel.trim();
        if (!label) {
            // Empty or whitespace-only: nothing added, no event.
            return;
        }
        // Timestamp + counter keeps ids unique even against parent-supplied ids.
        const id = `new-${Date.now()}-${this.nextId++}`;
        // Replace the array (rather than mutating it) so reactivity is guaranteed.
        this._items = [...this._items, { id, label, done: false }];
        this.newLabel = '';
        // Event name is lower case; detail carries the label that was added.
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        // dataset values are always strings; task ids may be numbers, so compare as strings.
        const id = event.target.dataset.id;
        this._items = this._items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }
}
