/**
 * @description Sets each contact's current employer by maintaining the NPSP
 *              Affiliation record between the contact and the (existing,
 *              Organization) employer account.
 *
 *              This class deliberately uses NPSP's standard mechanism: it only
 *              performs DML on npe5__Affiliation__c and lets the NPSP
 *              affiliation trigger handlers (Affiliations_TDTM et al.) do the
 *              rest, namely:
 *                - updating Contact.npsp__Primary_Affiliation__c to the
 *                  organization of the new Current/Primary affiliation;
 *                - demoting the previously Current/Primary affiliation to
 *                  Former, non-primary, with npe5__EndDate__c = today;
 *                - leaving the contact's household (Contact.AccountId) intact,
 *                  because the employer is an Organization account, not a
 *                  Household account.
 *
 *              Limits: at most 2 SOQL queries and 2 DML statements of its own
 *              (one insert + one update on Affiliation), bulk-safe for 200+ contacts.
 */
public with sharing class EmployerService {

    private static final String AFFILIATION_STATUS_CURRENT = 'Current';

    /**
     * @description For each contact, ensures a Current, primary NPSP affiliation
     *              exists between the contact and the given Organization account.
     *
     * @param employerByContactId Map of Contact Id -> Organization Account Id.
     *                            Null or empty map is a no-op. Invalid Ids, Ids
     *                            of the wrong sObject type, and contacts that no
     *                            longer exist are skipped.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // 1. No-op for null or empty input.
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // 2. Sanitize input: keep only well-formed Contact Id keys with
        //    well-formed Account Id values.
        Map<Id, Id> targetOrgByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId == null || orgId == null) {
                continue;
            }
            if (contactId.getSObjectType() != Contact.SObjectType
                    || orgId.getSObjectType() != Account.SObjectType) {
                continue;
            }
            targetOrgByContactId.put(contactId, orgId);
        }
        if (targetOrgByContactId.isEmpty()) {
            return;
        }

        // 3. SOQL #1: the contacts. AccountId is the household (Household
        //    Account model); we never touch it.
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id,
                   AccountId,
                   npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :targetOrgByContactId.keySet()
        ]);

        // 4. SOQL #2: any existing affiliation between these contacts and these
        //    organizations (either direction of history: Current or Former).
        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c,
                   npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :targetOrgByContactId.keySet()
              AND npe5__Organization__c IN :targetOrgByContactId.values()
        ];
        Map<String, npe5__Affiliation__c> existingByKey = new Map<String, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : existingAffiliations) {
            existingByKey.put(affiliationKey(aff.npe5__Contact__c, aff.npe5__Organization__c), aff);
        }

        // 5. Build the work lists.
        Date today = Date.today();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();

        for (Id contactId : targetOrgByContactId.keySet()) {
            // Skip contacts that no longer exist (deleted or not visible).
            if (!contactsById.containsKey(contactId)) {
                continue;
            }

            Id orgId = targetOrgByContactId.get(contactId);
            npe5__Affiliation__c existing =
                existingByKey.get(affiliationKey(contactId, orgId));

            if (existing != null) {
                if (existing.npe5__Status__c == AFFILIATION_STATUS_CURRENT
                        && existing.npe5__Primary__c) {
                    // Already the Current, primary employer affiliation:
                    // nothing changes, no duplicate is created.
                    continue;
                }
                // Revive/correct the existing affiliation for this pair.
                existing.npe5__Status__c = AFFILIATION_STATUS_CURRENT;
                existing.npe5__Primary__c = true;
                if (existing.npe5__StartDate__c == null) {
                    existing.npe5__StartDate__c = today;
                }
                // Clear any stale end date; NPSP will end the previous primary
                // employer with today's date via its trigger handlers.
                existing.npe5__EndDate__c = null;
                affiliationsToUpdate.add(existing);
            } else {
                // Brand-new employer affiliation. NPSP's trigger handlers will:
                //   - end the previous Current/Primary affiliation
                //     (Former, non-primary, EndDate = today);
                //   - set Contact.npsp__Primary_Affiliation__c to orgId;
                //   - leave the household assignment untouched.
                affiliationsToInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = AFFILIATION_STATUS_CURRENT,
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today
                ));
            }
        }

        // 6. DML #1 and #2 (each guarded so an empty list does not count/fire).
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }

    /**
     * @description Composite key for looking up an existing affiliation by
     *              contact + organization.
     */
    private static String affiliationKey(Id contactId, Id orgId) {
        return String.valueOf(contactId) + '-' + String.valueOf(orgId);
    }
}
