/**
 * RecurringGiftService
 *
 * Creates Enhanced Recurring Donations (npe03__Recurring_Donation__c) for monthly
 * giving sign-ups submitted by an external donation form.
 *
 * Design notes:
 *  - Fully bulk-safe: validates every request up front, then performs exactly one
 *    DML statement regardless of how many requests are passed in. No SOQL is used.
 *  - NPSP's Enhanced Recurring Donations feature generates the installment
 *    Opportunities; this service never creates Opportunities itself.
 *  - dayOfMonth = 31 is stored using ERD's native "always use last day of month"
 *    option (npsp__Always_Use_Last_Day_Of_Month__c) so short months are handled
 *    correctly. 29 and 30 are stored as plain day-of-month values.
 *  - installments null or 0 => open-ended recurring donation; otherwise a
 *    fixed-length recurring donation with that many planned installments.
 */
public inherited sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String RD_PERIOD_MONTHLY = 'Monthly';
    private static final String RD_SCHEDULE_TYPE_CUSTOM = 'Custom';
    private static final String RD_STATUS_ACTIVE = 'Active';
    private static final String RD_RECURRING_TYPE_OPEN = 'Open';
    private static final String RD_RECURRING_TYPE_FIXED = 'Fixed';
    private static final String RD_OPEN_ENDED_STATUS_OPEN = 'Open';
    private static final String RD_OPEN_ENDED_STATUS_FIXED = 'Fixed';

    /**
     * Creates one Enhanced Recurring Donation per request.
     *
     * @param requests the list of gift sign-up requests; may be null or empty
     * @return the Ids of the newly created Recurring Donations, in request order
     * @throws RecurringGiftService.RecurringGiftException if any request is invalid
     *         (thrown before any DML is executed)
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate every request before building any records so that a single
        // bad request prevents all DML (all-or-nothing, per requirements).
        validateRequests(requests);

        List<npe03__Recurring_Donation__c> recurringDonations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            recurringDonations.add(buildRecurringDonation(request));
        }

        insert recurringDonations;

        List<Id> recurringDonationIds = new List<Id>();
        for (npe03__Recurring_Donation__c recurringDonation : recurringDonations) {
            recurringDonationIds.add(recurringDonation.Id);
        }
        return recurringDonationIds;
    }

    private static void validateRequests(List<GiftRequest> requests) {
        List<String> errors = new List<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            Integer requestNumber = i + 1;

            if (request == null) {
                errors.add('Request ' + requestNumber + ': request cannot be null.');
                continue;
            }
            if (request.contactId == null) {
                errors.add('Request ' + requestNumber + ': contactId is required.');
            }
            if (request.amount == null || request.amount <= 0) {
                errors.add('Request ' + requestNumber
                    + ': amount must be greater than zero.');
            }
            if (request.dayOfMonth == null || request.dayOfMonth < 1
                || request.dayOfMonth > 31) {
                errors.add('Request ' + requestNumber
                    + ': dayOfMonth must be between 1 and 31.');
            }
            if (request.startDate == null) {
                errors.add('Request ' + requestNumber + ': startDate is required.');
            }
        }

        if (!errors.isEmpty()) {
            throw new RecurringGiftException(
                'Invalid recurring gift request(s): ' + String.join(errors, ' | '));
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(
        GiftRequest request) {

        Boolean isFixedLength = request.installments != null && request.installments > 0;
        Boolean alwaysUseLastDayOfMonth = request.dayOfMonth == 31;

        npe03__Recurring_Donation__c recurringDonation =
            new npe03__Recurring_Donation__c(
                // Donor
                npe03__Contact__c = request.contactId,
                npe03__Organization__c = null,

                // Money
                npe03__Amount__c = request.amount,

                // Monthly schedule, every 1 month, on the requested day of month
                npe03__Installment_Period__c = RD_PERIOD_MONTHLY,
                npsp__InstallmentFrequency__c = 1,
                npsp__Day_of_Month__c = String.valueOf(request.dayOfMonth),
                npsp__Always_Use_Last_Day_Of_Month__c = alwaysUseLastDayOfMonth,

                // Open-ended vs fixed-length
                npsp__RecurringType__c = isFixedLength
                    ? RD_RECURRING_TYPE_FIXED
                    : RD_RECURRING_TYPE_OPEN,
                npe03__Open_Ended_Status__c = isFixedLength
                    ? RD_OPEN_ENDED_STATUS_FIXED
                    : RD_OPEN_ENDED_STATUS_OPEN,
                npe03__Installments__c = isFixedLength ? request.installments : null,
                npe03__Schedule_Type__c = RD_SCHEDULE_TYPE_CUSTOM,

                // Dates and status
                npe03__Date_Established__c = request.startDate,
                npe03__Next_Payment_Date__c = request.startDate,
                npsp__StartDate__c = request.startDate,
                npsp__Status__c = RD_STATUS_ACTIVE,

                // Payment method exactly as submitted by the form
                npsp__PaymentMethod__c = request.paymentMethod
            );

        return recurringDonation;
    }
}
