/**
 * @description Service for replacing an Opportunity's GAU Allocations with
 *              percentage-based allocations across restricted funds (GAUs).
 *
 *              Each allocation stores both npsp__Percent__c and npsp__Amount__c.
 *              Because npsp__Percent__c is populated, NPSP keeps the allocation
 *              amounts in sync if the Opportunity Amount changes later (e.g. a
 *              $1,000 gift split 60/40 corrected to $2,000 becomes $1,200/$800)
 *              with no additional code required.
 *
 *              All validation happens before any DML so the operation is
 *              all-or-nothing from the caller's perspective.
 *
 *              Bulk-safe: no SOQL or DML inside loops.
 */
public inherited sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Integer MAX_PERCENT = 100;
    private static final Integer AMOUNT_SCALE = 2;

    /**
     * @description Replaces all existing GAU Allocations of the given Opportunity
     *              with one allocation per map entry. Amounts are derived from the
     *              Opportunity's current Amount; percents are persisted so NPSP
     *              recalculates amounts if the Opportunity Amount changes later.
     * @param opportunityId  Id of the Opportunity to allocate.
     * @param percentByGauId Map of GAU Id -> percentage (60 means 60%).
     *                       A total below 100% is allowed; the remainder stays
     *                       unallocated.
     * @return The inserted npsp__Allocation__c records (with Ids populated).
     * @throws AllocationException if the map is null/empty, any percentage is null
     *         or not greater than 0, percentages sum to more than 100, or any GAU
     *         is inactive (or does not exist).
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        validateInput(opportunityId, percentByGauId);

        // Query GAUs once, outside any loop, and verify each is active.
        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, Name, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :percentByGauId.keySet()]
        );
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'General Accounting Unit ' + gauId + ' does not exist.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit "' + gau.Name + '" (' + gauId + ') is inactive.');
            }
        }

        // Fetch the Opportunity to base amounts on its current Amount.
        List<Opportunity> opportunities = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' does not exist.');
        }
        Decimal opportunityAmount = opportunities[0].Amount == null ? 0 : opportunities[0].Amount;

        // Query existing allocations once, outside any loop.
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        // All validation passed: replace the existing allocations.
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            allocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent,
                npsp__Amount__c = (opportunityAmount * percent / 100)
                                      .setScale(AMOUNT_SCALE, RoundingMode.HALF_UP)
            ));
        }

        insert allocations;

        return allocations;
    }

    /**
     * @description Validates the request before any SOQL or DML is executed.
     * @throws AllocationException for any invalid input as specified by the contract.
     */
    private static void validateInput(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id must not be null.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException(
                'The percentage map must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must not be null.');
            }
            if (percent <= 0) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            totalPercent += percent;
        }

        if (totalPercent > MAX_PERCENT) {
            throw new AllocationException(
                'Total percentage must not exceed 100. Provided total: ' + totalPercent + '.');
        }
        // A total below 100% is intentionally allowed; the remainder stays unallocated.
    }
}
