/**
 * @description Service that converts an open donation (pledge) with NPSP Payments
 * enabled into a monthly installment plan.
 *
 * Paid and written-off payments are treated as history and are never modified.
 * All other (unpaid, not written off) payments are deleted and replaced by a
 * schedule of new unpaid payments, one per month starting on the given first
 * payment date. The payments split the outstanding amount (opportunity Amount
 * minus paid/written-off payment amounts) as evenly as possible, with the last
 * payment absorbing any rounding remainder so the schedule adds up exactly.
 *
 * All validation happens before any DML, so an invalid request changes nothing.
 */
public inherited sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    private static final Integer CURRENCY_SCALE = 2;

    /**
     * @description Replaces an opportunity's open (unpaid, not written off)
     * payments with a monthly installment schedule.
     * @param opportunityId    Id of the open donation (Opportunity) to schedule.
     * @param numberOfPayments  Number of monthly installments to create (>= 1).
     * @param firstPaymentDate  Scheduled date of the first installment; each
     *                          subsequent installment is one month later.
     * @return The inserted payments, in schedule order.
     * @throws PaymentPlanService.PaymentPlanException if the request is invalid
     *         (bad installment count, closed opportunity, or no outstanding
     *         amount). In that case no data is changed.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {

        // ------------------------------------------------------------------
        // Input validation (no DML has happened yet, so nothing can change)
        // ------------------------------------------------------------------
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be provided and must be at least 1.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('firstPaymentDate must be provided.');
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opportunity = opportunities[0];

        if (opportunity.IsClosed) {
            throw new PaymentPlanException('Cannot schedule payments for a closed opportunity.');
        }

        // ------------------------------------------------------------------
        // Load existing payments and classify them
        // ------------------------------------------------------------------
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal historyAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            if (payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true) {
                // Paid and written-off payments are history: keep them and
                // count their amounts against the opportunity total.
                historyAmount += (payment.npe01__Payment_Amount__c == null ? 0 : payment.npe01__Payment_Amount__c);
            } else {
                paymentsToDelete.add(payment);
            }
        }

        // ------------------------------------------------------------------
        // Compute the outstanding amount and the per-installment amounts
        // ------------------------------------------------------------------
        Decimal opportunityAmount = (opportunity.Amount == null ? 0 : opportunity.Amount);
        Decimal outstandingAmount = opportunityAmount - historyAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('The outstanding amount must be greater than zero.');
        }

        // Even share, rounded down to the cent.
        Decimal installmentAmount = outstandingAmount.divide(numberOfPayments, CURRENCY_SCALE, RoundingMode.DOWN);

        // The last installment absorbs the rounding remainder so the schedule
        // sums exactly to the outstanding amount.
        Decimal lastInstallmentAmount = outstandingAmount - (installmentAmount * (numberOfPayments - 1));

        // ------------------------------------------------------------------
        // Build the new payment schedule
        // ------------------------------------------------------------------
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c newPayment = new npe01__OppPayment__c(
                npe01__Opportunity__c    = opportunityId,
                npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastInstallmentAmount : installmentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c           = false,
                npe01__Written_Off__c    = false
            );
            newPayments.add(newPayment);
        }

        // ------------------------------------------------------------------
        // DML: delete the open payments, then insert the new schedule.
        // All validation has passed at this point; both DML statements are
        // all-or-nothing for the records passed to them.
        // ------------------------------------------------------------------
        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }
        insert newPayments;

        return newPayments;
    }
}
