/**
 * FamilyService
 *
 * Imports parent/child links from an external student system into NPSP
 * Relationships (npe4__Relationship__c).
 *
 * Design notes:
 * - We insert exactly ONE relationship record per pair, in the direction
 *   Contact = child, RelatedContact = parent, Type = 'Parent'.
 *   Because this org uses the NPSP "List Setting" reciprocal method, the NPSP
 *   Relationship trigger automatically creates the reciprocal record
 *   (Contact = parent, RelatedContact = child) whose Type is resolved through
 *   the npe4__Relationship_Lookup__c record named 'Parent'
 *   (Male -> Son, Female -> Daughter, Neutral -> Child).
 *   This guarantees exactly one record in each direction and keeps us
 *   gender-agnostic (we never need to read the parent's Gender field).
 * - Re-run safety: before inserting, we query all relationships that exist
 *   between the contacts involved in this call (either direction) and skip any
 *   pair that already has a relationship, as well as duplicate pairs inside
 *   the incoming map itself.
 * - Limits: for 200 pairs this performs exactly 1 SOQL query and 1 DML
 *   statement (insert). The reciprocal records are created by NPSP's own
 *   trigger, which does not count against our statement limits.
 */
public with sharing class FamilyService {

    @AuraEnabled
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input does nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every contact involved in this call so a single query can
        // find all existing relationships between them (in either direction).
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                allContactIds.add(childId);
            }
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                allContactIds.add(parentId);
            }
        }
        if (allContactIds.isEmpty()) {
            return;
        }

        // Single SOQL query: any relationship record whose two contacts are
        // both part of this import. Each such record represents an existing
        // link between two contacts in the set, in either direction.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
        ]) {
            if (rel.npe4__Contact__c != null && rel.npe4__RelatedContact__c != null) {
                existingPairs.add(
                    pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c)
                );
            }
        }

        List<npe4__Relationship__c> newRelationships =
            new List<npe4__Relationship__c>();
        // Guards against duplicate pairs within the same map, including a
        // pair supplied as (child -> parent) and again as (parent -> child).
        Set<String> queuedPairs = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Skip incomplete or nonsensical entries.
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String key = pairKey(childId, parentId);

            // Skip if a relationship already exists between the two contacts
            // (in either direction) or we already queued this exact pair.
            if (existingPairs.contains(key) || queuedPairs.contains(key)) {
                continue;
            }
            queuedPairs.add(key);

            // Create the child -> parent direction only. NPSP's List Setting
            // reciprocal method creates the parent -> child record (Son /
            // Daughter / Child, based on the parent's gender) automatically.
            newRelationships.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        // Single DML statement. NPSP's trigger handles the reciprocals.
        if (!newRelationships.isEmpty()) {
            insert newRelationships;
        }
    }

    /**
     * Direction-independent key for a pair of contacts, so a relationship
     * stored as (A, B) matches a requested pair of (B, A).
     */
    private static String pairKey(Id contactA, Id contactB) {
        String a = String.valueOf(contactA);
        String b = String.valueOf(contactB);
        return a.compareTo(b) < 0 ? a + '-' + b : b + '-' + a;
    }
}
