```apex
public with sharing class EmployeeDirectoryService {

    /**
     * Returns the FB_Employee__c records the running user can see via sharing,
     * ordered by Name ascending. Only fields the running user has FLS read
     * access to are included; inaccessible fields are omitted entirely (not
     * returned as null). Returns an empty list if the user cannot read the
     * object at all. Never bypasses sharing (class is with sharing and no
     * strip-inaccessible/without sharing escapes are used).
     */
    public static List<FB_Employee__c> getDirectory() {
        // Object-level accessibility check: if the user cannot read the
        // object, return an empty list instead of throwing.
        Schema.DescribeSObjectResult objDesc = Schema.SObjectType.FB_Employee__c;
        if (!objDesc.isQueryable() || !objDesc.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Determine which of the custom fields the running user can read (FLS).
        List<String> fieldNames = new List<String>{ 'Id', 'Name' };
        appendIfAccessible(fieldNames, FB_Employee__c.Department__c);
        appendIfAccessible(fieldNames, FB_Employee__c.Salary__c);
        appendIfAccessible(fieldNames, FB_Employee__c.Personal_Email__c);

        String query = 'SELECT ' + String.join(fieldNames, ', ') +
                       ' FROM FB_Employee__c' +
                       ' ORDER BY Name ASC';

        return Database.query(query);
    }

    private static void appendIfAccessible(List<String> fieldNames, Schema.SObjectField field) {
        if (field.getDescribe().isAccessible()) {
            fieldNames.add(String.valueOf(field));
        }
    }
}
