```apex
/**
 * TAF action: creates an onboarding Task for the owner of each newly created
 * Account whose Type is 'Customer - Direct' or 'Customer - Channel'.
 *
 * Runs in the after insert context so every account already has an Id for
 * Task.WhatId. All tasks are collected and inserted with a single DML
 * statement, and no DML is performed when no account qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    @TestVisible
    private static final Set<String> QUALIFYING_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    @TestVisible
    private static final Integer DUE_IN_DAYS = 7;

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> onboardingTasks = new List<Task>();

        for (SObject record : triggerNew) {
            Account account = (Account) record;
            if (account.Type != null && QUALIFYING_TYPES.contains(account.Type)) {
                onboardingTasks.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = Date.today().addDays(DUE_IN_DAYS),
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }
}
```

