/**
 * DML-less unit tests for TA_Opportunity_GuardAmountDecrease, following the
 * Trigger Actions Framework (TAF) testing recommendation: build triggerNew and
 * triggerOld in memory, generate Ids with TriggerTestUtility.getFakeId, and
 * invoke the action's context method (beforeUpdate) directly. No DML, no SOQL.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static final String ERROR_MESSAGE = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

    /**
     * Invokes the action's before-update context method directly with
     * in-memory lists, bypassing the trigger and any database activity.
     */
    private static void runAction(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        TriggerAction.BeforeUpdate action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);
    }

    /**
     * Builds an in-memory Opportunity with a fake Id so that the action's
     * oldMap lookups resolve without any database insert.
     */
    private static Opportunity buildOpp(Id recordId, Decimal amount) {
        Opportunity opp = new Opportunity(
            Id = recordId,
            Amount = amount
        );
        return opp;
    }

    @IsTest
    static void testReductionOfMoreThanHalfIsRejected() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{ buildOpp(fakeId, 499) };
        List<Opportunity> triggerOld = new List<Opportunity>{ buildOpp(fakeId, 1000) };

        Test.startTest();
        runAction(triggerNew, triggerOld);
        Test.stopTest();

        Opportunity result = triggerNew[0];
        Assert.isTrue(result.hasErrors(), 'A reduction from 1000 to 499 must produce an error.');
        Assert.areEqual(1, result.getErrors().size(),
            'Exactly one error must be added, but found: ' + result.getErrors().size());
        Assert.areEqual(ERROR_MESSAGE, result.getErrors()[0].getMessage(),
            'The error must carry the action\'s ERROR_MESSAGE constant exactly.');
    }

    @IsTest
    static void testReductionOfExactlyHalfIsAccepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{ buildOpp(fakeId, 500) };
        List<Opportunity> triggerOld = new List<Opportunity>{ buildOpp(fakeId, 1000) };

        Test.startTest();
        runAction(triggerNew, triggerOld);
        Test.stopTest();

        Opportunity result = triggerNew[0];
        Assert.isFalse(result.hasErrors(),
            'A reduction of exactly half (1000 to 500) is allowed and must not error.');
        Assert.areEqual(0, result.getErrors().size(), 'No errors are expected.');
    }

    @IsTest
    static void testIncreaseIsAccepted() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{ buildOpp(fakeId, 2000) };
        List<Opportunity> triggerOld = new List<Opportunity>{ buildOpp(fakeId, 1000) };

        Test.startTest();
        runAction(triggerNew, triggerOld);
        Test.stopTest();

        Opportunity result = triggerNew[0];
        Assert.isFalse(result.hasErrors(), 'An increase in Amount must not produce an error.');
        Assert.areEqual(0, result.getErrors().size(), 'No errors are expected.');
    }

    @IsTest
    static void testNullPreviousAmountIsAcceptedWithoutException() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{ buildOpp(fakeId, 10) };
        List<Opportunity> triggerOld = new List<Opportunity>{ buildOpp(fakeId, null) };

        Decimal resultValue;
        Test.startTest();
        // The action must skip the comparison when the previous Amount is null
        // rather than throwing a NullPointerException or adding an error.
        runAction(triggerNew, triggerOld);
        resultValue = triggerNew[0].Amount;
        Test.stopTest();

        Opportunity result = triggerNew[0];
        Assert.isFalse(result.hasErrors(),
            'A record whose previous Amount was null must be accepted without error.');
        Assert.areEqual(0, result.getErrors().size(), 'No errors are expected.');
        Assert.areEqual(10, resultValue, 'The in-memory Amount must remain unchanged.');
    }

    @IsTest
    static void testMixedRecordsOnlyViolatorsGetErrors() {
        // violating: 1000 -> 499 (more than half reduction)
        Id violatingId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        // allowed: 1000 -> 500 (exactly half reduction)
        Id exactHalfId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        // allowed: 1000 -> 1000 (unchanged)
        Id unchangedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        // allowed: 1000 -> 1500 (increase)
        Id increasedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerNew = new List<Opportunity>{
            buildOpp(violatingId, 499),
            buildOpp(exactHalfId, 500),
            buildOpp(unchangedId, 1000),
            buildOpp(increasedId, 1500)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            buildOpp(violatingId, 1000),
            buildOpp(exactHalfId, 1000),
            buildOpp(unchangedId, 1000),
            buildOpp(increasedId, 1000)
        };

        Test.startTest();
        runAction(triggerNew, triggerOld);
        Test.stopTest();

        Map<Id, Opportunity> newById = new Map<Id, Opportunity>(triggerNew);

        Opportunity violating = newById.get(violatingId);
        Assert.isTrue(violating.hasErrors(), 'Only the record reducing 1000 to 499 must error.');
        Assert.areEqual(1, violating.getErrors().size(),
            'The violating record must carry exactly one error.');
        Assert.areEqual(ERROR_MESSAGE, violating.getErrors()[0].getMessage(),
            'The error message must match the action\'s ERROR_MESSAGE constant.');

        for (Id okId : new List<Id>{ exactHalfId, unchangedId, increasedId }) {
            Opportunity ok = newById.get(okId);
            Assert.isFalse(ok.hasErrors(),
                'Record ' + okId + ' does not break the rule and must have no errors.');
            Assert.areEqual(0, ok.getErrors().size(),
                'Record ' + okId + ' must carry no errors.');
        }
    }
}
