/**
 * Trigger Action for the Trigger Actions Framework (Contact, before insert / before update).
 *
 * Rule: two Contacts of the same Account may not share an email address
 * (case-insensitive). Contacts without an Account or without an Email are not checked.
 *
 * - A violating contact gets a record-level error; valid contacts in the same save
 *   are unaffected (partial saves work).
 * - Within a single save, the first contact per (Account, email) is accepted and
 *   each later one is rejected.
 * - On update, only contacts whose Email or AccountId changed are checked, and a
 *   contact never conflicts with itself.
 * - Bulk-safe: at most one SOQL query per trigger execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void validate(List<Contact> newList, List<Contact> oldList) {
        // Collect the contacts that need checking.
        List<Contact> contactsToCheck = new List<Contact>();
        // On update, the rows whose Email/AccountId changed. Their pre-save database
        // values must be ignored both as conflict sources and as "self".
        Set<Id> changedContactIds = new Set<Id>();

        for (Integer i = 0; i < newList.size(); i++) {
            Contact c = newList[i];
            if (c.Email == null || c.AccountId == null) {
                continue;
            }
            if (oldList != null) {
                Contact oldC = oldList[i];
                if (c.Email == oldC.Email && c.AccountId == oldC.AccountId) {
                    // Unrelated edit: do not check, so legacy duplicates never block it.
                    continue;
                }
                changedContactIds.add(c.Id);
            }
            contactsToCheck.add(c);
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Resolve within-save duplicates: the first contact per (Account, email) key
        // is the candidate; every later one is rejected outright.
        Map<String, Contact> firstCandidateByKey = new Map<String, Contact>();
        List<Contact> inSaveDuplicates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : contactsToCheck) {
            String key = buildKey(c);
            if (firstCandidateByKey.containsKey(key)) {
                inSaveDuplicates.add(c);
            } else {
                firstCandidateByKey.put(key, c);
                accountIds.add(c.AccountId);
                emails.add(c.Email);
            }
        }

        // Single SOQL query: existing contacts that already occupy one of the
        // (Account, email) pairs. SOQL text comparisons (Email) are case-insensitive;
        // rows for contacts in this save whose Email/AccountId changed are excluded,
        // which also guarantees a contact never conflicts with itself. An empty
        // changedContactIds (insert) simply matches every row.
        Map<String, Id> existingIdByKey = new Map<String, Id>();
        for (Contact existing : [
            SELECT AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emails
              AND Id NOT IN :changedContactIds
        ]) {
            if (existing.Email == null || existing.AccountId == null) {
                continue;
            }
            existingIdByKey.put(
                String.valueOf(existing.AccountId) + '|' + existing.Email.toLowerCase(),
                existing.Id
            );
        }

        // Record-level errors on the violating contacts only; valid contacts in the
        // same save are untouched, so partial saves work.
        for (String key : firstCandidateByKey.keySet()) {
            if (existingIdByKey.containsKey(key)) {
                firstCandidateByKey.get(key).addError(ERROR_MESSAGE);
            }
        }
        for (Contact c : inSaveDuplicates) {
            c.addError(ERROR_MESSAGE);
        }
    }

    private static String buildKey(Contact c) {
        return String.valueOf(c.AccountId) + '|' + c.Email.toLowerCase();
    }
}
