/**
 * @description Trigger Action that normalizes contact information on every Lead
 *              as it is created, before the record is saved to the database.
 *              Runs in the before insert context, so no additional DML and no
 *              SOQL are required, and it is inherently bulk-safe (it simply
 *              iterates over the records in the triggering batch).
 *
 *              - Email:    leading/trailing whitespace removed, lower-cased.
 *                          A null email stays null.
 *              - Company:  leading/trailing whitespace removed.
 *              - LeadSource: set to 'Web' when blank; an existing value is kept.
 *
 *              Registered via the Trigger_Action__mdt record
 *              TA_Lead_NormalizeContactInfo (Order 10) on the Lead
 *              sObject_Trigger_Setting__mdt record.
 *
 * @group       Trigger Actions Framework
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    /**
     * @description Default value assigned to LeadSource when the incoming
     *              record does not carry one.
     */
    @TestVisible
    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /**
     * @description Normalizes Email, Company and LeadSource on every Lead in
     *              the before insert context. Mutating the records in place
     *              here means the values are already clean when the record is
     *              first saved — no extra DML and no SOQL are used, and the
     *              implementation is bulk-safe for up to 200 records per chunk.
     *
     * @param triggerNew The list of new Leads being inserted.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Lead lead = (Lead) record;
            normalizeEmail(lead);
            normalizeCompany(lead);
            defaultLeadSource(lead);
        }
    }

    /**
     * @description Trims leading/trailing whitespace and lower-cases the email.
     *              A null email is left as null.
     */
    private void normalizeEmail(Lead lead) {
        String email = lead.Email;
        if (email != null) {
            lead.Email = email.trim().toLowerCase();
        }
    }

    /**
     * @description Trims leading/trailing whitespace from the company name.
     */
    private void normalizeCompany(Lead lead) {
        String company = lead.Company;
        if (company != null) {
            lead.Company = company.trim();
        }
    }

    /**
     * @description Sets LeadSource to 'Web' when it is blank
     *              (null or whitespace only); an existing value is kept.
     */
    private void defaultLeadSource(Lead lead) {
        if (String.isBlank(lead.LeadSource)) {
            lead.LeadSource = DEFAULT_LEAD_SOURCE;
        }
    }
}
