```apex
/**
 * @description Trigger Action for the Trigger Actions Framework (Case, after insert /
 * after update / after delete / after undelete).
 *
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's Cases with
 * IsClosed = false. Cases without an Account are ignored. An account whose last open
 * case goes away is explicitly set to 0 (never blank).
 *
 * Performance: per trigger execution the action issues at most two SOQL queries
 * (one aggregate on Case, one on Account) and at most one DML statement (update on the
 * affected Accounts, only when the value actually changes). Because the action writes to
 * Account - which has no trigger in this org - it does not re-enter the Case trigger.
 *
 * Recalculation is always done from a fresh aggregate query, so the action is idempotent
 * and self-correcting regardless of the operation that fired the trigger.
 */
public inherited sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate,
                   TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    private static final String FIELD_ACCOUNT_ID = 'AccountId';
    private static final String FIELD_IS_CLOSED = 'IsClosed';
    private static final String FIELD_OPEN_CASE_COUNT = 'FB_Open_Case_Count__c';

    /**
     * @description After insert: accounts of the new cases (open or already closed)
     * must be recalculated. Closed-on-insert cases contribute nothing, but the account
     * still gets its correct value (0 instead of blank if it had none).
     */
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            accountIds.add((Id) record.get(FIELD_ACCOUNT_ID));
        }
        recalculate(accountIds);
    }

    /**
     * @description After update: recalculate only when the closed state or the parent
     * account changed (covers close, reopen, and move to another account). Both the new
     * and the old account are recalculated when a case is moved.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            SObject newRecord = triggerNew[i];
            SObject oldRecord = triggerOld[i];
            Boolean isClosedChanged = newRecord.get(FIELD_IS_CLOSED) != oldRecord.get(FIELD_IS_CLOSED);
            Boolean accountChanged = newRecord.get(FIELD_ACCOUNT_ID) != oldRecord.get(FIELD_ACCOUNT_ID);
            if (isClosedChanged || accountChanged) {
                accountIds.add((Id) newRecord.get(FIELD_ACCOUNT_ID));
                accountIds.add((Id) oldRecord.get(FIELD_ACCOUNT_ID));
            }
        }
        recalculate(accountIds);
    }

    /**
     * @description After delete: the deleted rows no longer appear in the aggregate
     * query, so the remaining open-case counts (including 0) are written back.
     */
    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerOld) {
            accountIds.add((Id) record.get(FIELD_ACCOUNT_ID));
        }
        recalculate(accountIds);
    }

    /**
     * @description After undelete: the restored cases are visible to the aggregate
     * query, so the affected accounts get their counts back.
     */
    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            accountIds.add((Id) record.get(FIELD_ACCOUNT_ID));
        }
        recalculate(accountIds);
    }

    /**
     * @description Recomputes the open case count for the given accounts with one
     * aggregate SOQL query and writes back the changed accounts with one DML statement.
     * @param accountIds the accounts touched by the trigger; nulls and duplicates are tolerated
     */
    private void recalculate(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 1: current number of open cases per affected account.
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
                SELECT AccountId, COUNT(Id) openCount
                FROM Case
                WHERE AccountId IN :accountIds
                AND IsClosed = false
                GROUP BY AccountId
        ]) {
            openCountByAccountId.put((Id) result.get('AccountId'), (Integer) result.get('openCount'));
        }

        // Query 2: read the stored value so we only DML accounts that really change
        // (also converts blank to 0 where required).
        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds
        ]) {
            Integer targetCount = openCountByAccountId.containsKey(account.Id)
                    ? openCountByAccountId.get(account.Id)
                    : 0;
            if (account.get(FIELD_OPEN_CASE_COUNT) != targetCount) {
                accountsToUpdate.add(new Account(
                        Id = account.Id,
                        FB_Open_Case_Count__c = targetCount
                ));
            }
        }

        // Single DML statement. Updating Account does not re-fire the Case trigger
        // (Account has no trigger in this org), so no recursion guard is required.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
