```apex
/**
 * @description After-update Trigger Action for Opportunity (Trigger Actions Framework).
 * Finance audit trail: whenever an Opportunity's Amount changes on update, create a
 * completed Task with Subject 'Amount changed' on the Opportunity.
 *
 * Recursion safety: other registered actions (e.g. TA_Opportunity_RoundAmount at order 20)
 * may re-update the same opportunities within the same transaction. The rounding update is a
 * consequence of the user's change, not a separate change, so this action guarantees at most
 * one 'Amount changed' Task per Opportunity per transaction by tracking every Opportunity
 * evaluated in this transaction in a static Set. The first execution for a given record
 * evaluates the user's change (triggerNew vs triggerOld); any later execution for the same
 * record in the same transaction is skipped, even if Amount differs again between those
 * executions (e.g. rounding). Static state is per-transaction, so deduplication resets on the
 * next transaction and genuine changes in later transactions are still audited.
 *
 * Bulk safety: builds all Tasks in memory and performs a single insert DML per trigger
 * execution; handles the full 200-record trigger chunk.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    @TestVisible
    private static final String TASK_SUBJECT = 'Amount changed';
    @TestVisible
    private static final String TASK_STATUS = 'Completed';

    /**
     * @description Opportunity Ids already evaluated in the current transaction.
     *              Prevents duplicate audit Tasks from recursive updates
     *              performed by other actions in the same transaction.
     */
    @TestVisible
    private static Set<Id> evaluatedRecordIds = new Set<Id>();

    /**
     * @description Creates one completed Task per Opportunity whose Amount changed,
     *              at most one per Opportunity per transaction.
     * @param triggerNew The updated Opportunity records.
     * @param triggerOld The Opportunity records before the update.
     */
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (triggerNew == null || triggerOld == null || triggerNew.isEmpty()) {
            return;
        }

        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> auditTasks = new List<Task>();

        for (Opportunity opp : triggerNew) {
            if (opp.Id == null || evaluatedRecordIds.contains(opp.Id)) {
                continue;
            }
            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }
            // Mark this record as evaluated for the whole transaction, regardless of
            // whether its Amount changed, so the rounding re-update cannot produce a
            // second audit Task (nor a false positive on records the user did not touch).
            evaluatedRecordIds.add(opp.Id);

            // Null-safe value comparison: fires only when the Amount actually changed.
            if (opp.Amount != oldOpp.Amount) {
                auditTasks.add(new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = opp.Id,
                    Status = TASK_STATUS
                ));
            }
        }

        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }
}
