public inherited sharing class TA_Contact_Queries {

	@testVisible
	private static TA_Contact_Queries instance;

	/**
	 * Parent Account records for the contacts in the current trigger execution,
	 * keyed by Account Id. Populated by the inner Service action, which must run
	 * first in the before insert context. Re-queried on every trigger execution
	 * because later DML in the same transaction can involve other accounts.
	 */
	public Map<Id, Account> accountsById;

	private TA_Contact_Queries() {
		accountsById = new Map<Id, Account>();
	}

	public static TA_Contact_Queries getInstance() {
		if (instance == null) {
			instance = new TA_Contact_Queries();
		}
		return instance;
	}

	private void run(List<Contact> triggerNew) {
		Set<Id> accountIds = new Set<Id>();
		for (Contact contact : triggerNew) {
			if (contact.AccountId != null) {
				accountIds.add(contact.AccountId);
			}
		}
		accountsById = accountIds.isEmpty()
			? new Map<Id, Account>()
			: new Map<Id, Account>([
				SELECT
					Id,
					BillingStreet,
					BillingCity,
					BillingPostalCode,
					BillingCountry,
					AccountSource
				FROM Account
				WHERE Id IN :accountIds
			]);
	}

	/**
	 * Trigger action that loads the shared query results. Registered first in
	 * before insert (Order__c 1) so it runs before the actions that consume
	 * the map, giving exactly one Account query per trigger execution.
	 */
	public inherited sharing class Service implements TriggerAction.BeforeInsert {

		public void beforeInsert(List<SObject> triggerNew) {
			TA_Contact_Queries queries = TA_Contact_Queries.getInstance();
			queries.run((List<Contact>) triggerNew);
		}
	}
}
